window.kbPageData["views/entry/k-50c7fc725f90e378"] = {"key":"entry/k-50c7fc725f90e378","state":{"route":"entry/k-50c7fc725f90e378"},"node":{"id":"k-50c7fc725f90e378","mode":"k","title":"动物逃逸期间的致害责任","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["承租人占有租赁物期间租赁物致第三人损害的责任归属"],"qs":["江苏 2024 C类 行测#8"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"《中华人民共和国民法典》第一千二百四十五条规定，饲养的动物致害，原则上由动物饲养人或者管理人承担侵权责任。第一千二百四十九条规定，动物在遗弃、逃逸期间致害，由动物原饲养人或者管理人承担侵权责任。","review":{"definition":"《中华人民共和国民法典》第一千二百四十五条规定，饲养的动物致害，原则上由动物饲养人或者管理人承担侵权责任。第一千二百四十九条规定，动物在遗弃、逃逸期间致害，由动物原饲养人或者管理人承担侵权责任。","explanation":"题中耕牛在交由沈某照管后走失。按题意，若果园损害发生在耕牛脱离沈某控制、尚未被农场实际接管期间，沈某作为逃逸前的管理人依法承担侵权责任，支持A项。已支付的2万元是沈某与刘某就耕牛走失约定的赔偿，不能据此确定农场的果园损失。原解析引用的第七百四十九条位于融资租赁合同章，本题给出的是普通租赁关系。","references":[{"source":"web-340d5d1801bcd9a2","location":"合同编第十五章第七百四十九条","quote":"承租人占有租赁物期间"},{"source":"web-340d5d1801bcd9a2","location":"侵权责任编第九章第一千二百四十五条、第一千二百四十九条","quote":"由动物原饲养人或者管理人承担侵权责任"}],"evidence":"因沈某照管不周，耕牛走失","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#8":{"paper":"江苏 2024 C类 行测","n":8,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",2],"asrc":["02d6b49839583bdaf297.pdf",3],"card":"2097d0ba8fb4c574729ec14c","links":[{"id":"k-50c7fc725f90e378","role":"直接考查","why":"本案适用承租人占有期间租赁物致第三人损害的规则，由承租人承担果园损失的赔偿责任。"}]}},"terms":{},"references":{"web-340d5d1801bcd9a2":{"name":"《中华人民共和国民法典》","url":"https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/bgt/art/2023/art_60fb3863b7364b759123a42d1df568ca.html"}},"topics":[],"units":{"k-50c7fc725f90e378":[["江苏 2024 C类 行测#8"]]}};
